<script setup lang="ts">
import { useQuery } from '@tanstack/vue-query'
import ExecutionVariables from './ExecutionVariables.vue'
import type { Project } from '~~/shared/types/projects'
import type { ExecutionDocument, ExecutionKind, ProjectExecution } from '~~/shared/types/project-execution'
import { defaultExecutionKit, defaultExecutionState, executionStateSchema, executionMoney, renderExecutionDocument } from '~~/shared/utils/project-execution'
const props=defineProps<{project:Project}>(),auth=useAuthStore(),supabase=useNuxtApp().$supabase
const query=useQuery({queryKey:computed(()=>['account',auth.user?.id,'project-execution',props.project.id]),queryFn:({signal})=>sharedRequest<ProjectExecution>(`/api/projects/${props.project.id}/execution`,{signal}),retry:false})
const state=ref(defaultExecutionState()),base=ref(''),revision=ref(0),estimateRevision=ref(0),loaded=ref(false)
const selected=ref(''),active=ref('contract'),tab=ref('legal'),search=ref(''),busy=ref(false),exporting=ref(''),error=ref(''),templatesOpen=ref(false),templateKind=ref<ExecutionKind>('contract'),previewOpen=ref(true),resetOpen=ref(false)
const dirty=computed(()=>loaded.value&&JSON.stringify(state.value)!==base.value)
const editable=computed(()=>props.project.permission!=='viewer')
function load(data:ProjectExecution){state.value=JSON.parse(JSON.stringify(data.state));base.value=JSON.stringify(data.state);revision.value=data.revision;estimateRevision.value=data.estimateRevision;loaded.value=true;if(!data.contracts.some(row=>row.id===selected.value))selected.value=data.contracts[0]?.id??''}
watch(()=>query.data.value,data=>{if(data&&!dirty.value)load(data)},{immediate:true})
const contracts=computed(()=>query.data.value?.contracts??[]),contract=computed(()=>contracts.value.find(row=>row.id===selected.value))
const groups=computed(()=>{
 const data=query.data.value;if(!data)return []
 const companies=data.estimate.counterparties.filter(p=>!!p.isOwnLegalEntity===(tab.value==='legal'))
 return companies.map(p=>({party:p,rows:contracts.value.filter(c=>[c.sellerId,c.buyerId].includes(p.id)&&`${p.company} ${p.inn} ${c.number} ${c.seller} ${c.buyer}`.toLocaleLowerCase('ru').includes(search.value.toLocaleLowerCase('ru').trim()))})).filter(g=>g.rows.length).sort((a,b)=>Number(b.rows.some(c=>c.source==='revenue'))-Number(a.rows.some(c=>c.source==='revenue'))||a.party.company.localeCompare(b.party.company,'ru'))
})
const kit=computed(()=>state.value.kits.find(row=>row.contractId===selected.value)??defaultExecutionKit(selected.value))
const kind=computed<ExecutionKind>(()=>active.value==='contract'?'contract':active.value==='invoice'?'invoice':'appendix')
const document=computed(()=>kind.value==='contract'?kit.value.contract:kind.value==='invoice'?kit.value.prepayment.document:kit.value.appendices.find(row=>row.id===active.value))
const title=computed(()=>document.value?.title??state.value.templates[kind.value].title),body=computed(()=>document.value?.body??state.value.templates[kind.value].body)
const rendered=computed(()=>{if(!query.data.value||!contract.value)return null;try{return renderExecutionDocument({...query.data.value,state:state.value},selected.value,kind.value,kind.value==='appendix'?active.value:undefined)}catch{return null}})
function ensure(){let row=state.value.kits.find(row=>row.contractId===selected.value);if(!row){row=defaultExecutionKit(selected.value);state.value.kits.push(row)}return row}
function editDoc(key:keyof ExecutionDocument,value:string|null){if(!editable.value||!selected.value)return;const k=ensure(),doc=kind.value==='contract'?k.contract:kind.value==='invoice'?k.prepayment.document:k.appendices.find(row=>row.id===active.value);if(doc)doc[key]=value as never}
function select(id:string){selected.value=id;active.value='contract';error.value=''}
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow'}).format(new Date())
function addAppendix(){const k=ensure();let n=1;while(k.appendices.some(row=>row.number===String(n)))n++;const id=crypto.randomUUID();k.appendices.push({id,number:String(n),date:today(),title:null,body:null});active.value=id}
function setPrepayment(enabled:boolean){const k=ensure();k.prepayment.enabled=enabled;if(enabled){if(!k.prepayment.document.number)k.prepayment.document.number=`АВ-${contract.value?.number??''}`;if(!k.prepayment.document.date)k.prepayment.document.date=today();active.value='invoice'}else if(active.value==='invoice')active.value='contract'}
function removeAppendix(){const k=ensure();k.appendices=k.appendices.filter(row=>row.id!==active.value);active.value='contract'}
function resetKit(){state.value.kits=state.value.kits.filter(row=>row.contractId!==selected.value);active.value='contract';resetOpen.value=false}
async function save(){
 if(!editable.value||busy.value)return;const parsed=executionStateSchema.safeParse(state.value);if(!parsed.success){error.value=parsed.error.issues[0]?.message??'Проверьте поля';return}
 busy.value=true;error.value='';const user=auth.user?.id
 try{await sharedRequest(`/api/projects/${props.project.id}/execution`,{method:'PUT',body:{revision:revision.value,estimateRevision:estimateRevision.value,state:parsed.data}});if(auth.user?.id!==user)return;const result=await query.refetch();if(result.data)load(result.data)}catch(e:any){error.value=e?.data?.message||e.message}finally{busy.value=false}
}
async function reload(){if(dirty.value&&!window.confirm('Отменить несохранённые изменения и загрузить актуальные данные?'))return;const result=await query.refetch();if(result.data)load(result.data)}
async function download(format:'docx'|'pdf'){
 if(dirty.value||exporting.value)return;exporting.value=format;error.value='';const user=auth.user?.id
 try{const{data}=await supabase.auth.getSession();if(!data.session||data.session.user.id!==user)throw Error('Войдите в аккаунт');const blob=await $fetch<Blob>(`/api/projects/${props.project.id}/execution/export`,{method:'POST',retry:0,responseType:'blob',headers:{Authorization:`Bearer ${data.session.access_token}`},body:{contractId:selected.value,kind:kind.value,...(kind.value==='appendix'?{appendixId:active.value}:{}),format}});if(auth.user?.id!==user)return;const url=URL.createObjectURL(blob),link=window.document.createElement('a');link.href=url;link.download=`${(rendered.value?.title??'Документ').replace(/[\\/:*?"<>|]/g,'-')}.${format}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);const result=await query.refetch();if(result.data&&!dirty.value)load(result.data)}catch(e:any){if(e?.data instanceof Blob){try{error.value=JSON.parse(await e.data.text()).message}catch{error.value='Не удалось сформировать документ'}}else error.value=e?.data?.message||e.message}finally{exporting.value=''}
}
watch(editable,value=>{if(!value){templatesOpen.value=false;resetOpen.value=false;if(query.data.value)load(query.data.value)}})
onBeforeRouteLeave(()=>!dirty.value||window.confirm('В документах есть несохранённые изменения. Покинуть страницу?'))
const kindOptions=[{label:'Договор',value:'contract'},{label:'Приложение',value:'appendix'},{label:'Счёт на предоплату',value:'invoice'}]
</script>
<template>
 <section class="execution-workspace" aria-label="Исполнение проекта">
  <div class="execution-toolbar"><div><h2>Документы проекта</h2><p>Комплект основного заказчика — первым. Суммы и реквизиты связаны со сметой и договорами.</p></div><div class="execution-actions"><UButton color="neutral" variant="outline" icon="i-lucide-refresh-cw" label="Обновить" :disabled="busy" @click="reload"/><UButton color="neutral" variant="outline" icon="i-lucide-file-pen-line" label="Шаблоны документов" :disabled="!loaded||busy" @click="templatesOpen=true"/><UButton v-if="editable" label="Сохранить изменения" :loading="busy" :disabled="!dirty||!loaded" @click="save"/></div></div>
  <UAlert v-if="error" color="error" :description="error" class="mb-4"/>
  <p v-if="query.isPending.value">Загружаем документы…</p><UAlert v-else-if="query.error.value" color="error" title="Не удалось загрузить исполнение" :actions="[{label:'Повторить',onClick:reload}]"/>
  <template v-else-if="loaded">
   <div v-if="!contracts.length" class="execution-empty"><UIcon name="i-lucide-files"/><h2>Начните с договора основного заказчика</h2><p>Добавьте договоры с суммами из сметы — здесь появятся комплекты документов.</p><UButton :to="`/projects/${project.id}/contracts`" label="Открыть договоры"/></div>
   <template v-else>
    <nav class="execution-tabs" aria-label="Участники исполнения"><button :aria-pressed="tab==='legal'" @click="tab='legal'">Юр. Лица</button><button :aria-pressed="tab==='external'" @click="tab='external'">Контрагенты</button></nav>
    <div class="execution-layout">
     <aside class="execution-sidebar"><UInput v-model="search" icon="i-lucide-search" placeholder="Компания, ИНН или договор" aria-label="Поиск в исполнении" class="w-full"/><div v-if="!groups.length" class="execution-muted py-5">В этом разделе договоры не найдены.</div><section v-for="group in groups" :key="group.party.id" class="execution-party"><h3>{{group.party.company}}</h3><small>ИНН {{group.party.inn||'не указан'}}</small><button v-for="row in group.rows" :key="row.id" class="execution-contract" :aria-pressed="row.id===selected" @click="select(row.id)"><span v-if="row.source==='revenue'" class="execution-primary">Основной заказчик</span><strong>Договор № {{row.number}}</strong><span>{{row.source==='revenue'?'Нам оплачивают':'Мы оплачиваем'}}</span><span>{{row.source==='revenue'?row.buyer:row.seller}}</span><b>{{row.amount===null?'Проверьте смету':executionMoney(row.amount)}}</b></button></section><NuxtLink :to="`/projects/${project.id}/contracts`" class="subscription-card-link">Реестр договоров →</NuxtLink></aside>
     <div v-if="contract" class="execution-main">
      <header class="execution-kit-header"><div><span v-if="contract.source==='revenue'" class="execution-primary">Основной заказчик · первый комплект</span><h2>Договор № {{contract.number}}</h2><p>{{contract.seller}} → {{contract.buyer}}</p></div><strong>{{contract.amount===null?'—':executionMoney(contract.amount)}}</strong></header>
      <UAlert v-if="contract.issue" color="error" :description="contract.issue"/>
      <div class="execution-documents" aria-label="Порядок документов"><button :aria-pressed="active==='contract'" @click="active='contract'"><UIcon name="i-lucide-file-signature"/>1. Договор</button><button v-for="(appendix,index) in kit.appendices" :key="appendix.id" :aria-pressed="active===appendix.id" @click="active=appendix.id"><UIcon name="i-lucide-file-plus-2"/>{{index+2}}. Приложение № {{appendix.number}}</button><button v-if="kit.prepayment.enabled" :aria-pressed="active==='invoice'" @click="active='invoice'"><UIcon name="i-lucide-receipt"/>{{kit.appendices.length+2}}. Счёт · {{kit.prepayment.percent}}%</button></div>
      <div class="execution-kit-controls"><UButton v-if="editable" color="neutral" variant="outline" label="Добавить приложение" icon="i-lucide-plus" :disabled="kit.appendices.length>=100||busy" @click="addAppendix"/><UCheckbox :model-value="kit.prepayment.enabled" label="Счёт на предоплату" :disabled="!editable||busy" @update:model-value="setPrepayment(!!$event)"/><UFormField v-if="kit.prepayment.enabled" label="Предоплата, %"><UInput :model-value="kit.prepayment.percent" type="number" :min="0.01" :max="100" :step="0.01" :disabled="!editable||busy" aria-label="Процент предоплаты" class="w-28" @update:model-value="ensure().prepayment.percent=Number($event)"/></UFormField><span v-if="kit.prepayment.enabled&&contract.amount!==null" class="execution-muted">К оплате {{executionMoney(Math.round(contract.amount*kit.prepayment.percent)/100)}}</span></div>
      <section v-if="document" class="execution-editor"><div class="execution-editor-heading"><h3>{{kind==='contract'?'Договор':kind==='appendix'?'Приложение':'Счёт на предоплату'}}</h3><div class="execution-actions"><UButton v-if="editable&&kind==='appendix'" color="error" variant="ghost" label="Удалить приложение" :disabled="busy" @click="removeAppendix"/><UButton v-if="editable" color="neutral" variant="ghost" label="Использовать шаблон" :disabled="busy" @click="editDoc('title',null);editDoc('body',null)"/></div></div>
       <div v-if="kind!=='contract'" class="execution-meta"><UFormField label="Номер" required><UInput :model-value="document.number" :maxlength="100" :disabled="!editable||busy" class="w-full" @update:model-value="editDoc('number',String($event))"/></UFormField><UFormField label="Дата"><UInput :model-value="document.date" type="date" :disabled="!editable||busy" class="w-full" @update:model-value="editDoc('date',String($event))"/></UFormField></div>
       <p v-else class="execution-muted">Номер, стороны, дата и срок берутся из <NuxtLink :to="`/projects/${project.id}/contracts`">реестра договоров</NuxtLink>.</p>
       <UFormField label="Заголовок документа"><UInput :model-value="title" :maxlength="200" :disabled="!editable||busy" class="w-full" @update:model-value="editDoc('title',String($event))"/></UFormField>
       <UFormField label="Текст документа" description="Переменные в {{двойных скобках}} заполняются из проекта, сметы и договора."><UTextarea :model-value="body" :rows="12" :maxlength="20000" :disabled="!editable||busy" class="w-full" @update:model-value="editDoc('body',String($event))"/></UFormField>
       <ExecutionVariables :disabled="!editable||busy" @insert="editDoc('body',body+'\n{{'+$event+'}}')"/>
       <div class="execution-export"><UButton color="neutral" variant="outline" :label="previewOpen?'Скрыть предпросмотр':'Предпросмотр'" icon="i-lucide-eye" @click="previewOpen=!previewOpen"/><div class="execution-actions"><span v-if="dirty" class="execution-muted">Перед экспортом сохраните изменения</span><UButton label="Word" color="neutral" variant="outline" icon="i-lucide-file-text" :disabled="dirty||!!exporting||!rendered||!!contract.issue" :loading="exporting==='docx'" @click="download('docx')"/><UButton label="PDF" color="neutral" variant="outline" icon="i-lucide-file-down" :disabled="dirty||!!exporting||!rendered||!!contract.issue" :loading="exporting==='pdf'" @click="download('pdf')"/></div></div>
      </section>
      <article v-if="previewOpen&&rendered" class="execution-preview" aria-label="Предпросмотр документа"><h2>{{rendered.title}}</h2><template v-for="(block,index) in rendered.blocks" :key="index"><p v-if="block.type==='text'">{{block.text}}</p><div v-else class="execution-table-scroll"><table><thead><tr><th v-for="(heading,i) in block.headers" :key="i">{{heading}}</th></tr></thead><tbody><tr v-for="(row,j) in block.rows" :key="j"><td v-for="(value,k) in row" :key="k">{{value}}</td></tr></tbody></table></div></template></article>
      <div v-if="editable&&state.kits.some(k=>k.contractId===selected)" class="execution-reset"><UButton label="Сбросить комплект документов" color="neutral" variant="ghost" :disabled="busy" @click="resetOpen=true"/></div>
     </div>
    </div>
   </template>
  </template>
  <UModal v-model:open="templatesOpen" title="Шаблоны документов" description="Общие шаблоны этого проекта. Изменения применяются к документам без индивидуального текста." :ui="{content:'sm:max-w-3xl'}"><template #body><div class="execution-template-form"><USelect v-model="templateKind" :items="kindOptions" aria-label="Тип шаблона"/><UFormField label="Заголовок"><UInput v-model="state.templates[templateKind].title" :disabled="!editable||busy" :maxlength="200" class="w-full"/></UFormField><UFormField label="Текст шаблона"><UTextarea v-model="state.templates[templateKind].body" :rows="16" :maxlength="20000" :disabled="!editable||busy" class="w-full"/></UFormField><p class="execution-muted">positions — таблица позиций; requisites — реквизиты; amount и vat — сумма и НДС документа; contractAmount — полная сумма договора; percent — процент предоплаты. Счёт автоматически использует сумму предоплаты.</p><ExecutionVariables :disabled="!editable||busy" @insert="state.templates[templateKind].body+='\n{{'+$event+'}}'"/><UButton label="Готово" @click="templatesOpen=false"/><p class="execution-muted">После закрытия нажмите «Сохранить изменения».</p></div></template></UModal>
  <UModal v-model:open="resetOpen" title="Сбросить комплект документов?" description="Приложения, настройки предоплаты и индивидуальный текст будут удалены. Сам договор в реестре сохранится."><template #body><div class="execution-actions"><UButton label="Сбросить" color="error" @click="resetKit"/><UButton label="Отмена" color="neutral" variant="outline" @click="resetOpen=false"/></div><p class="execution-muted mt-4">Для применения сброса сохраните изменения.</p></template></UModal>
 </section>
</template>
<style scoped>
.execution-workspace{color:#475569}.execution-toolbar,.execution-kit-header,.execution-editor-heading,.execution-export{display:flex;justify-content:space-between;align-items:center;gap:20px}.execution-toolbar{margin-bottom:28px;align-items:flex-start}.execution-toolbar h2,.execution-kit-header h2{font-size:22px;font-weight:650;color:#334155}.execution-toolbar p,.execution-kit-header p{font-size:14px;color:#8797ad;margin-top:8px}.execution-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.execution-tabs{display:flex;gap:6px;padding:6px;background:#edf0f5;border:1px solid #e2e8f0;border-radius:16px;width:fit-content;margin-bottom:24px}.execution-tabs button{padding:12px 24px;border-radius:11px;font-weight:600;color:#8292a8}.execution-tabs button[aria-pressed=true]{background:#fff;color:#334155;box-shadow:0 2px 8px #0f172a08}.execution-layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:28px;align-items:start}.execution-sidebar{border:1px solid #e2e8f0;background:#ffffffb8;padding:20px;border-radius:20px}.execution-party{margin:24px 0}.execution-party h3{font-size:14px;font-weight:650}.execution-party small{font-size:12px;color:#94a3b8}.execution-contract{display:flex;flex-direction:column;gap:7px;text-align:left;width:100%;margin-top:12px;border:1px solid #e2e8f0;border-radius:14px;background:white;padding:16px;font-size:13px}.execution-contract[aria-pressed=true]{border-color:var(--ui-primary,#27263f);box-shadow:0 0 0 1px var(--ui-primary,#27263f)}.execution-contract span{color:#8292a8;font-size:12px}.execution-contract b{margin-top:3px;color:#334155}.execution-primary{display:inline-block;font-size:11px!important;color:var(--ui-primary,#27263f)!important;background:#f1f0f6;padding:5px 8px;border-radius:6px;width:fit-content}.execution-main{min-width:0}.execution-kit-header{padding-bottom:24px;border-bottom:1px solid #e2e8f0;align-items:flex-start}.execution-kit-header h2{margin-top:8px}.execution-kit-header>strong{white-space:nowrap;margin-top:8px;font-size:20px}.execution-documents{display:flex;flex-wrap:wrap;gap:10px;padding:22px 0}.execution-documents button{display:flex;align-items:center;gap:8px;border:1px solid #dbe2ed;border-radius:10px;padding:10px 14px;font-size:13px;background:white}.execution-documents button[aria-pressed=true]{background:var(--ui-primary,#27263f);color:white;border-color:transparent}.execution-kit-controls{display:flex;flex-wrap:wrap;align-items:center;gap:18px;margin:0 0 24px}.execution-editor{background:#ffffffc9;border:1px solid #e2e8f0;border-radius:20px;padding:24px;display:grid;gap:20px}.execution-editor-heading h3{font-size:18px;font-weight:650}.execution-meta{display:grid;grid-template-columns:1fr 1fr;gap:16px}.execution-muted{color:#8797ad;font-size:13px;line-height:1.6}.execution-muted a{text-decoration:underline}.execution-variables{display:flex;flex-wrap:wrap;gap:6px}.execution-variables button{font-size:11px;background:#f1f3f7;border-radius:6px;padding:5px 8px;color:#64748b}.execution-preview{background:white;border:1px solid #e2e8f0;border-radius:16px;padding:40px;margin-top:24px;overflow-wrap:anywhere;line-height:1.8;font-size:14px}.execution-preview h2{color:#172334;font-size:23px;font-weight:650;margin-bottom:28px}.execution-preview p{white-space:pre-wrap;margin:18px 0}.execution-table-scroll{overflow-x:auto}.execution-preview table{width:100%;border-collapse:collapse;font-size:12px}.execution-preview th,.execution-preview td{padding:10px;border:1px solid #dce2ea;text-align:left}.execution-preview th{background:#f1f3f7}.execution-reset{margin-top:18px;text-align:right}.execution-template-form{display:grid;gap:18px}.execution-empty{text-align:center;padding:70px 24px;border:1px solid #e2e8f0;border-radius:24px}.execution-empty>.iconify{font-size:44px}.execution-empty h2{font-size:22px;margin:20px 0 10px}.execution-empty p{margin-bottom:24px;color:#8797ad}@media(max-width:1200px){.execution-toolbar{flex-direction:column}.execution-layout{grid-template-columns:250px minmax(0,1fr)}.execution-kit-header,.execution-export{align-items:flex-start;flex-direction:column}}@media(max-width:800px){.execution-layout{grid-template-columns:minmax(0,1fr)}.execution-sidebar{max-height:360px;overflow:auto}.execution-preview{padding:24px}.execution-meta{grid-template-columns:1fr}.execution-editor-heading{align-items:flex-start;flex-direction:column}.execution-editor{padding:18px}}
</style>
